//! C-ABI TypeSupport registration shim.
//!
//! Allows C (and any language with C FFI — Python ctypes, C# P/Invoke, Rust
//! extern "C", etc.) to register CDR-capable types with a DomainParticipant.
//! The primary use case is passing the `<Type>_compute_key_hash_from_cdr`/
//! `<Type>_compute_key_hash_from_cdr_key_only`/`<Type>_get_field_from_cdr`
//! functions generated by `zidl -b c` as the compute_key_hash/
//! compute_key_hash_key_only/get_field callbacks.
//!
//! Usage from C:
//!
//!   #include "zzdds_c.h"
//!
//!   zzdds_register_type_support(
//!       participant,
//!       "ShapeType",
//!       ShapeType_compute_key_hash_from_cdr,
//!       ShapeType_compute_key_hash_from_cdr_key_only,
//!       ShapeType_get_field_from_cdr
//!   );

const std = @import("std");
const DDS = @import("zzdds_generated").DDS;
const participant_mod = @import("../dcps/participant.zig");
const TypeSupport = participant_mod.TypeSupport;
const DomainParticipantImpl = participant_mod.DomainParticipantImpl;
const filter_mod = @import("../dcps/filter.zig");
const key_value = @import("../dcps/key_value.zig");
const nil = @import("../dcps/nil.zig");
const zidl_bindings = @import("zidl_bindings");
const extensions = @import("extensions.zig");

/// Discriminated field value shared with `zzdds_cft_match_sample`'s
/// `zzdds_filter_value` (see `extensions.zig`) — same C-ABI struct layout,
/// declared once there and reused here rather than duplicated.
pub const ZzddsFilterValue = extensions.ZzddsFilterValue;

fn zzddsFilterValueToZig(v: ZzddsFilterValue) ?filter_mod.FilterValue {
    return switch (v.kind) {
        0 => filter_mod.FilterValue{ .int = v.i },
        1 => filter_mod.FilterValue{ .float = v.f },
        2 => filter_mod.FilterValue{ .string = (v.s_ptr orelse return null)[0..v.s_len] },
        3 => filter_mod.FilterValue{ .float32 = @floatCast(v.f) },
        else => null,
    };
}

/// C-compatible compute_key_hash function type.
/// Matches the signature of `<Type>_compute_key_hash_from_cdr` generated by
/// `zidl -b c` (and `zidl -b cpp`).
///
/// Returns 0 (ZIDL_CDR_OK) on success, non-zero on parse failure.
pub const ZzddsComputeKeyHashFn = *const fn (
    payload: [*]const u8,
    len: usize,
    hash_out: *[16]u8,
) callconv(.c) c_int;

/// C-compatible get_field_from_cdr function type. Matches the signature of
/// `<Type>_get_field_from_cdr` generated by `zidl -b c`/`-b cpp`. See
/// `zzdds_get_field_from_cdr_fn`'s doc comment in zzdds_c.h for the
/// `scratch`/`scratch_len` contract (a matched string's bytes must be copied
/// there, not returned as a pointer into a local).
pub const ZzddsGetFieldFromCdrFn = *const fn (
    payload: [*]const u8,
    payload_len: usize,
    field: [*]const u8,
    field_len: usize,
    out: *ZzddsFilterValue,
    scratch: [*]u8,
    scratch_len: usize,
) callconv(.c) bool;

/// Per-registration adapter. Heap-allocated via the owning participant's
/// allocator (impl.alloc) when zzdds_register_type_support is called; freed
/// with the same allocator when the participant deinits or replaces this
/// registration.
///
/// Always allocated, even when both callbacks are null (a keyless,
/// non-filterable type) — a single unconditional shape here is simpler than
/// forking on "which callbacks were actually given" the way this used to
/// (before get_field existed) skip allocating anything at all for a null
/// compute_key_hash_fn. That old fast path would have been wrong anyway once
/// a keyless type could still want get_field_fn (a keyless struct can have
/// non-key fields a CFT expression filters on).
const CTypeSupportAdapter = struct {
    alloc: std.mem.Allocator,
    key_hash_fn: ?ZzddsComputeKeyHashFn,
    key_hash_only_fn: ?ZzddsComputeKeyHashFn,
    get_field_fn: ?ZzddsGetFieldFromCdrFn,

    fn computeKeyHash(ctx: *anyopaque, payload: []const u8) [16]u8 {
        const self: *CTypeSupportAdapter = @ptrCast(@alignCast(ctx));
        var hash: [16]u8 = std.mem.zeroes([16]u8);
        if (self.key_hash_fn) |f| _ = f(payload.ptr, payload.len, &hash);
        return hash;
    }

    fn computeKeyHashKeyOnly(ctx: *anyopaque, payload: []const u8) [16]u8 {
        const self: *CTypeSupportAdapter = @ptrCast(@alignCast(ctx));
        var hash: [16]u8 = std.mem.zeroes([16]u8);
        if (self.key_hash_only_fn) |f| _ = f(payload.ptr, payload.len, &hash);
        return hash;
    }

    fn getField(ctx: *anyopaque, payload: []const u8, field: []const u8, scratch: []u8) ?filter_mod.FilterValue {
        const self: *CTypeSupportAdapter = @ptrCast(@alignCast(ctx));
        const f = self.get_field_fn orelse return null;
        var out: ZzddsFilterValue = .{};
        if (!f(payload.ptr, payload.len, field.ptr, field.len, &out, scratch.ptr, scratch.len)) return null;
        return zzddsFilterValueToZig(out);
    }

    fn deinitAdapter(ctx: *anyopaque) void {
        const self: *CTypeSupportAdapter = @ptrCast(@alignCast(ctx));
        self.alloc.destroy(self);
    }
};

/// Register a C-ABI TypeSupport with a DomainParticipant.
///
/// @param participant          Public DDS_DomainParticipant handle (the boxed
///                             C-ABI opaque pointer, per zzdds_c.h's
///                             DDS_DomainParticipant typedef -- NOT the native
///                             Zig fat-pointer struct).
/// @param type_name            Null-terminated type name string.
/// @param compute_key_hash_fn  C function that computes the key hash from a
///                             raw, **complete ALIVE sample's** CDR bytes
///                             (encap header included) -- generated as
///                             `<Type>_compute_key_hash_from_cdr`.  Pass NULL
///                             for keyless types.
/// @param compute_key_hash_key_only_fn
///                             C function that computes the key hash from a
///                             raw, **genuine key-only** CDR payload (RTPS
///                             DISPOSE/UNREGISTER) -- generated as
///                             `<Type>_compute_key_hash_from_cdr_key_only`.
///                             Pass NULL for keyless types, or to accept the
///                             safe zero-hash fallback for that case (see
///                             `TypeSupport.compute_key_hash_key_only` in
///                             `dcps/participant.zig`).
/// @param get_field_fn         C function that extracts a named field from raw
///                             CDR bytes, for automatic ContentFilteredTopic
///                             filtering.  Pass NULL if the type has no
///                             filterable fields.
///
/// Returns 0 on success, -1 if the internal allocation failed.
pub export fn zzdds_register_type_support(
    participant: ?*anyopaque,
    type_name: [*:0]const u8,
    compute_key_hash_fn: ?ZzddsComputeKeyHashFn,
    compute_key_hash_key_only_fn: ?ZzddsComputeKeyHashFn,
    get_field_fn: ?ZzddsGetFieldFromCdrFn,
) callconv(.c) c_int {
    // The ABI parameter must be nullable: a non-null Zig pointer lets the
    // optimizer assume this check cannot fail in optimized builds.
    // zidl_bindings.unboxAs dereferences its argument unconditionally -- a literal
    // NULL passed by a C caller (a normal, expected "no object" value in C,
    // not UB) must be caught before unboxing, not after; nil.isNil only
    // catches an *already-unboxed* entity's ptr == NIL_PTR sentinel, which a
    // raw NULL C pointer would never reach without crashing first.
    const handle = participant orelse return -1;
    const p = zidl_bindings.unboxAsView(DDS.DomainParticipant, handle);
    if (nil.isNil(p)) return -1;
    const impl: *DomainParticipantImpl = @ptrCast(@alignCast(p.ptr));
    const name = std.mem.span(type_name);

    const adapter = impl.alloc.create(CTypeSupportAdapter) catch return -1;
    adapter.* = .{
        .alloc = impl.alloc,
        .key_hash_fn = compute_key_hash_fn,
        .key_hash_only_fn = compute_key_hash_key_only_fn,
        .get_field_fn = get_field_fn,
    };
    if (!impl.registerTypeSupport(name, TypeSupport{
        .ctx = adapter,
        .compute_key_hash = CTypeSupportAdapter.computeKeyHash,
        .compute_key_hash_key_only = CTypeSupportAdapter.computeKeyHashKeyOnly,
        // Per this entry point's contract, a keyed type passes its generated
        // `<Type>_compute_key_hash_from_cdr`; a keyless type passes NULL.
        .has_key = compute_key_hash_fn != null,
        .get_field = if (get_field_fn != null) CTypeSupportAdapter.getField else null,
        .deinit = CTypeSupportAdapter.deinitAdapter,
    })) {
        // registerTypeSupport consumes the adapter on failure as well.
        return -1;
    }

    return 0;
}

/// `ctx`-carrying compute_key_hash function type.
///
/// Unlike `ZzddsComputeKeyHashFn`, this variant carries a caller-owned `ctx`
/// through to every call — needed by any binding that can't generate a fresh,
/// uniquely-addressed native function per registered type the way `zidl -b c`/
/// `-b cpp` do (e.g. classic JNI: a Java `Class<?>` has no native function
/// pointer of its own, so one shared trampoline needs `ctx` to know which
/// class/method to dispatch to). C/C++/Zig callers don't need this — keep
/// using `zzdds_register_type_support` above.
pub const ZzddsComputeKeyHashCtxFn = *const fn (
    ctx: ?*anyopaque,
    payload: [*]const u8,
    len: usize,
    hash_out: *[16]u8,
) callconv(.c) c_int;

/// `ctx`-carrying get_field_from_cdr function type — see
/// `ZzddsComputeKeyHashCtxFn`'s doc comment for why this exists.
pub const ZzddsGetFieldFromCdrCtxFn = *const fn (
    ctx: ?*anyopaque,
    payload: [*]const u8,
    payload_len: usize,
    field: [*]const u8,
    field_len: usize,
    out: *ZzddsFilterValue,
    scratch: [*]u8,
    scratch_len: usize,
) callconv(.c) bool;

/// Per-registration adapter forwarding to a caller-supplied `ctx` (as opposed
/// to `CTypeSupportAdapter`, which wraps bare, type-specific C functions that
/// need no ctx of their own). Heap-allocated when
/// `zzdds_register_type_support_ctx` is called; freed (calling the caller's
/// own `user_deinit` first, if any) when the participant deinits or replaces
/// this TypeSupport registration — see `DomainParticipantImpl.deinit`/
/// `registerTypeSupport` in `src/dcps/participant.zig`, unchanged by this.
const CtxTypeSupportAdapter = struct {
    alloc: std.mem.Allocator,
    key_hash_fn: ?ZzddsComputeKeyHashCtxFn,
    key_hash_only_fn: ?ZzddsComputeKeyHashCtxFn,
    get_field_fn: ?ZzddsGetFieldFromCdrCtxFn,
    user_ctx: ?*anyopaque,
    user_deinit: ?*const fn (?*anyopaque) callconv(.c) void,

    fn computeKeyHash(ctx: *anyopaque, payload: []const u8) [16]u8 {
        const self: *CtxTypeSupportAdapter = @ptrCast(@alignCast(ctx));
        var hash: [16]u8 = std.mem.zeroes([16]u8);
        if (self.key_hash_fn) |f| _ = f(self.user_ctx, payload.ptr, payload.len, &hash);
        return hash;
    }

    fn computeKeyHashKeyOnly(ctx: *anyopaque, payload: []const u8) [16]u8 {
        const self: *CtxTypeSupportAdapter = @ptrCast(@alignCast(ctx));
        var hash: [16]u8 = std.mem.zeroes([16]u8);
        if (self.key_hash_only_fn) |f| _ = f(self.user_ctx, payload.ptr, payload.len, &hash);
        return hash;
    }

    fn getField(ctx: *anyopaque, payload: []const u8, field: []const u8, scratch: []u8) ?filter_mod.FilterValue {
        const self: *CtxTypeSupportAdapter = @ptrCast(@alignCast(ctx));
        const f = self.get_field_fn orelse return null;
        var out: ZzddsFilterValue = .{};
        if (!f(self.user_ctx, payload.ptr, payload.len, field.ptr, field.len, &out, scratch.ptr, scratch.len)) return null;
        return zzddsFilterValueToZig(out);
    }

    fn deinitAdapter(ctx: *anyopaque) void {
        const self: *CtxTypeSupportAdapter = @ptrCast(@alignCast(ctx));
        if (self.user_deinit) |f| f(self.user_ctx);
        self.alloc.destroy(self);
    }
};

/// Register a C-ABI TypeSupport with a DomainParticipant, with a `ctx`
/// forwarded to `compute_key_hash_fn`/`compute_key_hash_key_only_fn`/
/// `get_field_fn` on every call (the SAME ctx for all three — one shared
/// per-registration context, not several).
///
/// @param participant          Same as `zzdds_register_type_support`.
/// @param type_name            Null-terminated type name string.
/// @param compute_key_hash_fn  Function computing the key hash from a
///                             complete ALIVE sample's raw CDR bytes, given
///                             the `ctx` below. Pass NULL for keyless types.
/// @param compute_key_hash_key_only_fn
///                             Function computing the key hash from a
///                             genuine key-only CDR payload (RTPS
///                             DISPOSE/UNREGISTER), given the `ctx` below.
///                             Pass NULL for keyless types, or to accept the
///                             safe zero-hash fallback for that case.
/// @param get_field_fn         Function extracting a named field from raw CDR
///                             bytes, given the `ctx` below. Pass NULL if the
///                             type has no filterable fields.
/// @param ctx                  Opaque, caller-owned context passed to every
///                             `compute_key_hash_fn`/`compute_key_hash_key_only_fn`/
///                             `get_field_fn` call for this registration.
/// @param ctx_deinit           Optional cleanup for `ctx`, called exactly once
///                             when this registration is replaced or its
///                             participant is destroyed. NULL if `ctx` needs
///                             no cleanup (e.g. it isn't heap-allocated).
///
/// Returns 0 on success, -1 if the internal allocation failed.
pub export fn zzdds_register_type_support_ctx(
    participant: ?*anyopaque,
    type_name: [*:0]const u8,
    compute_key_hash_fn: ?ZzddsComputeKeyHashCtxFn,
    compute_key_hash_key_only_fn: ?ZzddsComputeKeyHashCtxFn,
    get_field_fn: ?ZzddsGetFieldFromCdrCtxFn,
    ctx: ?*anyopaque,
    ctx_deinit: ?*const fn (?*anyopaque) callconv(.c) void,
) callconv(.c) c_int {
    const handle = participant orelse return -1;
    const p = zidl_bindings.unboxAsView(DDS.DomainParticipant, handle);
    if (nil.isNil(p)) return -1;
    const impl: *DomainParticipantImpl = @ptrCast(@alignCast(p.ptr));
    const name = std.mem.span(type_name);

    const adapter = impl.alloc.create(CtxTypeSupportAdapter) catch return -1;
    adapter.* = .{
        .alloc = impl.alloc,
        .key_hash_fn = compute_key_hash_fn,
        .key_hash_only_fn = compute_key_hash_key_only_fn,
        .get_field_fn = get_field_fn,
        .user_ctx = ctx,
        .user_deinit = ctx_deinit,
    };
    if (!impl.registerTypeSupport(name, TypeSupport{
        .ctx = adapter,
        .compute_key_hash = CtxTypeSupportAdapter.computeKeyHash,
        .compute_key_hash_key_only = CtxTypeSupportAdapter.computeKeyHashKeyOnly,
        .has_key = compute_key_hash_fn != null,
        .get_field = if (get_field_fn != null) CtxTypeSupportAdapter.getField else null,
        .deinit = CtxTypeSupportAdapter.deinitAdapter,
    })) {
        // registerTypeSupport consumes the adapter on failure as well.
        return -1;
    }

    return 0;
}

/// Validate the complete value (or genuine key-only value), then publish its
/// hash. Unlike legacy hash callbacks, errors remain visible at ingress.
pub const ZzddsProcessSampleFn = *const fn ([*]const u8, usize, c_int, *[16]u8) callconv(.c) c_int;
pub const ZzddsProcessSampleCtxFn = *const fn (?*anyopaque, [*]const u8, usize, c_int, *[16]u8) callconv(.c) c_int;

const CheckedTypeSupportAdapter = struct {
    alloc: std.mem.Allocator,
    refs: std.atomic.Value(usize) = .init(1),
    process_fn: ?ZzddsProcessSampleFn = null,
    process_ctx_fn: ?ZzddsProcessSampleCtxFn = null,
    field_fn: ?ZzddsGetFieldFromCdrFn = null,
    field_ctx_fn: ?ZzddsGetFieldFromCdrCtxFn = null,
    user_ctx: ?*anyopaque = null,
    user_deinit: ?*const fn (?*anyopaque) callconv(.c) void = null,
    has_key: bool,

    fn retain(ctx: *anyopaque) void {
        const self: *@This() = @ptrCast(@alignCast(ctx));
        _ = self.refs.fetchAdd(1, .monotonic);
    }
    fn release(ctx: *anyopaque) void {
        const self: *@This() = @ptrCast(@alignCast(ctx));
        if (self.refs.fetchSub(1, .acq_rel) != 1) return;
        if (self.user_deinit) |f| f(self.user_ctx);
        self.alloc.destroy(self);
    }
    fn process(ctx: *anyopaque, payload: []const u8, kind: @import("../rtps/reader_sm.zig").ChangeKind, supplied: [16]u8) anyerror![16]u8 {
        const self: *@This() = @ptrCast(@alignCast(ctx));
        // Lifecycle notifications can carry only an inline key hash.
        if (kind != .alive and payload.len == 0) return if (self.has_key) supplied else @splat(0);
        var hash: [16]u8 = @splat(0);
        const key_only: c_int = @intFromBool(kind != .alive);
        const rc = if (self.process_fn) |f| f(payload.ptr, payload.len, key_only, &hash) else self.process_ctx_fn.?(self.user_ctx, payload.ptr, payload.len, key_only, &hash);
        if (rc != 0) return error.InvalidSample;
        return if (self.has_key) hash else @splat(0);
    }
    // Legacy key-recovery slots cannot signal failure. The checked processor
    // always supplies the actual hash, including when inline QoS supplied one.
    fn unusedHash(_: *anyopaque, _: []const u8) [16]u8 {
        return @splat(0);
    }
    fn getField(ctx: *anyopaque, payload: []const u8, field: []const u8, scratch: []u8) ?filter_mod.FilterValue {
        const self: *@This() = @ptrCast(@alignCast(ctx));
        var out: ZzddsFilterValue = .{};
        const ok = if (self.field_fn) |f| f(payload.ptr, payload.len, field.ptr, field.len, &out, scratch.ptr, scratch.len) else if (self.field_ctx_fn) |f| f(self.user_ctx, payload.ptr, payload.len, field.ptr, field.len, &out, scratch.ptr, scratch.len) else return null;
        return if (ok) zzddsFilterValueToZig(out) else null;
    }
    fn same(a: *anyopaque, b: *anyopaque) bool {
        const x: *@This() = @ptrCast(@alignCast(a));
        const y: *@This() = @ptrCast(@alignCast(b));
        return x.process_fn == y.process_fn and x.process_ctx_fn == y.process_ctx_fn and x.field_fn == y.field_fn and x.field_ctx_fn == y.field_ctx_fn and x.user_ctx == y.user_ctx and x.user_deinit == y.user_deinit and x.has_key == y.has_key;
    }
    fn install(self: *@This(), impl: *DomainParticipantImpl, name: []const u8) c_int {
        const ts = TypeSupport{
            .ctx = self,
            .has_key = self.has_key,
            .sample_processor = .{ .ctx = self, .process = process, .retain = retain, .release = release },
            .same_registration = same,
            .compute_key_hash = unusedHash,
            .compute_key_hash_key_only = unusedHash,
            .get_field = if (self.field_fn != null or self.field_ctx_fn != null) getField else null,
            .deinit = release,
        };
        const installed = impl.installCheckedTypeSupport(name, ts) catch {
            // Context ownership transfers only for a new successful install.
            self.alloc.destroy(self);
            return -1;
        };
        if (!installed) self.alloc.destroy(self);
        return 0;
    }
};

/// Checked registrations are immutable; install before creating topics.
/// Identical registrations are idempotent, conflicts/downgrades reject.
pub export fn zzdds_register_type_support_checked(participant: ?*anyopaque, type_name: [*:0]const u8, process_fn: ?ZzddsProcessSampleFn, has_key: c_int, field_fn: ?ZzddsGetFieldFromCdrFn) callconv(.c) c_int {
    const handle = participant orelse return -1;
    if (process_fn == null or (has_key != 0 and has_key != 1)) return -1;
    const p = zidl_bindings.unboxAsView(DDS.DomainParticipant, handle);
    if (nil.isNil(p)) return -1;
    const impl: *DomainParticipantImpl = @ptrCast(@alignCast(p.ptr));
    const adapter = impl.alloc.create(CheckedTypeSupportAdapter) catch return -1;
    adapter.* = .{ .alloc = impl.alloc, .process_fn = process_fn, .field_fn = field_fn, .has_key = has_key != 0 };
    return adapter.install(impl, std.mem.span(type_name));
}

/// ctx ownership transfers on a new successful install only. A repeated
/// identical ctx registration does not transfer or release it a second time.
pub export fn zzdds_register_type_support_checked_ctx(participant: ?*anyopaque, type_name: [*:0]const u8, process_fn: ?ZzddsProcessSampleCtxFn, has_key: c_int, field_fn: ?ZzddsGetFieldFromCdrCtxFn, ctx: ?*anyopaque, ctx_deinit: ?*const fn (?*anyopaque) callconv(.c) void) callconv(.c) c_int {
    const handle = participant orelse return -1;
    if (process_fn == null or (has_key != 0 and has_key != 1)) return -1;
    const p = zidl_bindings.unboxAsView(DDS.DomainParticipant, handle);
    if (nil.isNil(p)) return -1;
    const impl: *DomainParticipantImpl = @ptrCast(@alignCast(p.ptr));
    const adapter = impl.alloc.create(CheckedTypeSupportAdapter) catch return -1;
    adapter.* = .{ .alloc = impl.alloc, .process_ctx_fn = process_fn, .field_ctx_fn = field_fn, .has_key = has_key != 0, .user_ctx = ctx, .user_deinit = ctx_deinit };
    return adapter.install(impl, std.mem.span(type_name));
}

/// A type's key projection, as a binding generates it: writes the key-only
/// CDR of the complete sample `sample[0..sample_len]` (both with their
/// encapsulation header) to `out[0..out_size]` and its size to `*out_len`.
/// Returns DDS_RETCODE_OK; PRECONDITION_NOT_MET when the key does not fit,
/// with `*out_len` set to the size needed; or any other code if it cannot
/// project the sample. Pure: it must not call DDS operations.
pub const ZzddsProjectKeyFn = *const fn (
    ctx: ?*anyopaque,
    sample: [*]const u8,
    sample_len: usize,
    out: ?[*]u8,
    out_size: usize,
    out_len: *usize,
) callconv(.c) DDS.ReturnCode_t;

/// `key_value.KeyProjection` over a `ZzddsProjectKeyFn`.
const CKeyProjection = struct {
    alloc: std.mem.Allocator,
    func: ZzddsProjectKeyFn,
    user_ctx: ?*anyopaque,
    user_deinit: ?*const fn (?*anyopaque) callconv(.c) void,

    fn project(ctx: *anyopaque, sample: []const u8, allocator: std.mem.Allocator) ?[]u8 {
        const self: *CKeyProjection = @ptrCast(@alignCast(ctx));
        // Most keys are small: a stack buffer first, then the size asked for.
        var stack: [256]u8 = undefined;
        var len: usize = 0;
        var rc = self.func(self.user_ctx, sample.ptr, sample.len, &stack, stack.len, &len);
        if (rc == DDS.RETCODE_OK) return allocator.dupe(u8, stack[0..@min(len, stack.len)]) catch null;
        // The same sample always projects to the same key, so the second
        // call fits; a few more are only a guard against a projection that
        // reports sizes it then does not use.
        var tries: usize = 0;
        while (rc == DDS.RETCODE_PRECONDITION_NOT_MET and tries < 4) : (tries += 1) {
            const buf = allocator.alloc(u8, len) catch return null;
            rc = self.func(self.user_ctx, sample.ptr, sample.len, buf.ptr, buf.len, &len);
            if (rc == DDS.RETCODE_OK and len <= buf.len) {
                if (len == buf.len) return buf;
                defer allocator.free(buf);
                return allocator.dupe(u8, buf[0..len]) catch null;
            }
            allocator.free(buf);
        }
        return null;
    }

    fn deinit(ctx: *anyopaque) void {
        const self: *CKeyProjection = @ptrCast(@alignCast(ctx));
        if (self.user_deinit) |f| f(self.user_ctx);
        self.alloc.destroy(self);
    }
};

/// Gives the type `type_name`, already registered on `participant`, a key
/// projection: an instance then keeps the key-only CDR of its first alive
/// sample for get_key_value, not the sample. Writers and readers created
/// afterwards use it. Returns DDS_RETCODE_OK, and `ctx` passes to the
/// participant, which releases it with `ctx_deinit` (if not NULL) as it is
/// deleted, or at once if the type already has a projection, which it
/// keeps. BAD_PARAMETER for a NULL participant or `func`, or an unregistered
/// type, and OUT_OF_RESOURCES, leave `ctx` with the caller.
pub export fn zzdds_set_key_projection(
    participant: ?*anyopaque,
    type_name: [*:0]const u8,
    func: ?ZzddsProjectKeyFn,
    ctx: ?*anyopaque,
    ctx_deinit: ?*const fn (?*anyopaque) callconv(.c) void,
) callconv(.c) DDS.ReturnCode_t {
    const handle = participant orelse return DDS.RETCODE_BAD_PARAMETER;
    const f = func orelse return DDS.RETCODE_BAD_PARAMETER;
    const p = zidl_bindings.unboxAsView(DDS.DomainParticipant, handle);
    if (nil.isNil(p)) return DDS.RETCODE_BAD_PARAMETER;
    const impl: *DomainParticipantImpl = @ptrCast(@alignCast(p.ptr));
    const adapter = impl.alloc.create(CKeyProjection) catch return DDS.RETCODE_OUT_OF_RESOURCES;
    adapter.* = .{ .alloc = impl.alloc, .func = f, .user_ctx = ctx, .user_deinit = ctx_deinit };
    _ = impl.setKeyProjection(std.mem.span(type_name), .{ .ctx = adapter, .project = CKeyProjection.project }, CKeyProjection.deinit) catch |e| {
        impl.alloc.destroy(adapter);
        return switch (e) {
            error.TypeNotRegistered => DDS.RETCODE_BAD_PARAMETER,
            error.OutOfMemory => DDS.RETCODE_OUT_OF_RESOURCES,
        };
    };
    return DDS.RETCODE_OK;
}
